<main id="inhoud" class="wrap content-wrap post-list"><div class="eyebrow">Van 3DLens</div><h1 class="post-title"><?php if (is_home()) echo 'Nieuws & updates'; elseif (is_search()) echo 'Zoekresultaten'; else the_archive_title(); ?></h1>
